Soit le programme C suivant, composé de trois fonctions et de `main` :

```c
#include <stdio.h>

int carre(int x) {
    return x * x;
}

int somme_carres(int a, int b) {
    return carre(a) + carre(b);
}

void signaler(int s) {
    if (s > 50)
        printf("grand:%d\n", s);
    else
        printf("petit:%d\n", s);
}

int main() {
    int r = somme_carres(3, 4);
    signaler(r);
    signaler(somme_carres(5, 6));
    return 0;
}
```

